const body = $json.body ?? $json;
const headers = $json.headers ?? {};
const expected = $env.COUNCIL_WEBHOOK_SECRET;
if (!expected || headers['x-council-secret'] !== expected) throw new Error('Unauthorized council webhook request');
if (body.agent !== 'world') throw new Error('Phase 1 accepts only the world agent');
if (!body.user_message || !body.channel_id || !body.message_id) throw new Error('Invalid council payload');
return [{ json: {
  ok: true,
  message_id: String(body.message_id),
  channel_id: String(body.channel_id),
  agent: 'world',
  user_message: String(body.user_message).slice(0, 12000),
  openai_body: {
    model: $env.MYEONGHA_WORLD_MODEL || 'gpt-5-mini',
    instructions: '당신은 MyeongHa World Agent입니다. Worldbuilding, Character Experience, Narrative, Relationship Experience, character consistency를 검토합니다. 캐릭터를 상품 판매자처럼 다루지 마십시오. 서비스가 아는 것과 캐릭터가 아는 것을 구분하십시오. 관계, 기억, 서사 진행을 동일시하지 마십시오. 답변은 한국어로 작성하고, 결론·근거·주의점·다음 검증 항목 순서로 간결하게 제시하십시오. 아직 확정되지 않은 정책을 확정된 사실처럼 말하지 마십시오. 이번 Phase 1에서는 다른 Agent를 호출하지 말고 World 관점의 단독 검토만 수행하십시오.',
    input: String(body.user_message).slice(0, 12000),
    max_output_tokens: 900
  }
} }];

const response = $json;
const outputText = response.output_text || (Array.isArray(response.output) ? response.output.flatMap(item => Array.isArray(item.content) ? item.content : []).filter(item => item.type === 'output_text').map(item => item.text).join('\n') : '');
const content = String(outputText || '').trim();
if (!content) throw new Error('OpenAI returned no output text');
return [{ json: {
  ok: true,
  content: content.slice(0, 1900),
  model: response.model || null,
  request_id: response.id || null,
  usage: response.usage || null
} }];
